  /** Lets other nodes evaluate these definitions on node. */
  public static String serve(LawSpecRuntime.Node node) {
    var table = new java.util.HashMap<String, LawSpecRuntime.Definition>();
    for (var entry : DEFINITIONS.values()) table.put(entry.digest(), entry.definition());
    return node.serveDefinitions(table, TYPES);
  }

  /** The content hash of the definition with this qualified name. */
  public static String digest(String name) {
    return DEFINITIONS.get(name).digest();
  }

  /** Evaluates the named definition on the node at address, by its content hash; throws Unreachable when that node does not answer within 5 seconds. */
  public static LawSpecRuntime.Value evaluate(LawSpecRuntime.Node node, String address, String name, LawSpecRuntime.Value... args) {
    return evaluate(node, address, name, List.of(args), 5.0);
  }

  public static LawSpecRuntime.Value evaluate(
      LawSpecRuntime.Node node, String address, String name, List<LawSpecRuntime.Value> args, double timeout) {
    var entry = DEFINITIONS.get(name);
    if (entry == null) throw new IllegalArgumentException("no remote definition " + name);
    var definition = entry.definition();
    return node.evaluate(address, entry.digest(), args, definition.arguments(), definition.result(), TYPES, timeout);
  }
